@Composable
fun VoiceNoteButton(
 onStartRecording: () -> Unit,
 onStopRecording: () -> Unit,
 onCancelRecording: () -> Unit,
 setFabPosition: (x: Float, y: Float) -> Unit,
 modifier: Modifier = Modifier
) {
 var isPressed by remember { mutableStateOf(false) }
 var dragY by remember { mutableFloatStateOf(0f) }
 var wasCancelled by remember { mutableStateOf(false) }
 val iconSize by animateDpAsState(targetValue = if (isPressed) 32.dp else 24.dp, label = "IconSizeAnimation")

 val gestureModifier = Modifier.pointerInput(Unit) {
 detectTapGestures(
 onPress = {
 isPressed = true
 wasCancelled = false
 dragY = 0f
 onStartRecording()

 try {
 awaitRelease()
 if (!wasCancelled) {
 onStopRecording()
 }
 } finally {
 isPressed = false
 }
 }
 )
 }.pointerInput(isPressed) {
 if (isPressed) {
 detectDragGestures(
 onDrag = { change, dragAmount ->
 if (!wasCancelled) {
 dragY += dragAmount.y
 if (dragY < -200) {
 wasCancelled = true
 onCancelRecording()
 }
 change.consume()
 }
 },
 onDragEnd = { isPressed = false },
 onDragCancel = { isPressed = false }
 )
 }
 }

 val shouldCancel = dragY < -200

 Column(
 modifier = modifier,
 horizontalAlignment = Alignment.CenterHorizontally
 ) {
 AnimatedVisibility(
 visible = isPressed,
 enter = fadeIn(animationSpec = tween(100)),
 exit = fadeOut(animationSpec = tween(100))
 ) {
 Text(
 "Slide up to cancel",
 color = if (shouldCancel) Color.Red else Color.White,
 fontSize = 14.sp,
 fontWeight = FontWeight.Bold,
 textAlign = TextAlign.Center,
 modifier = Modifier.padding(bottom = 16.dp)
 )
 }

 Box(
 modifier = Modifier
 .then(gestureModifier)
 .shadow(elevation = 8.dp, shape = RoundedCornerShape(20.dp))
 .clip(RoundedCornerShape(20.dp))
 .background(color = Color(0xFF00a5cc))
 .padding(16.dp)
 .onGloballyPositioned { coordinates ->
 val x = coordinates.positionInRoot().x + coordinates.size.width / 2f
 val y = coordinates.positionInRoot().y + coordinates.size.height / 2f
 setFabPosition(x, y)
 }
 ) {
 Icon(
 painter = painterResource(id = R.drawable.icon_voice_white),
 contentDescription = "Record",
 tint = Color.White,
 modifier = Modifier.size(iconSize)
 )
 }
 }
}

private fun calculateMaxRadius(
 screenWidth: Float,
 screenHeight: Float,
 fabX: Float,
 fabY: Float
): Float {
 val distanceToTopLeft = sqrt(fabX * fabX + fabY * fabY)
 val distanceToTopRight = sqrt((screenWidth - fabX).pow(2) + fabY.pow(2))
 val distanceToBottomLeft = sqrt(fabX.pow(2) + (screenHeight - fabY).pow(2))
 val distanceToBottomRight = sqrt((screenWidth - fabX).pow(2) + (screenHeight - fabY).pow(2))

 return maxOf(
 distanceToTopLeft,
 distanceToTopRight,
 distanceToBottomLeft,
 distanceToBottomRight
 ) * 1.2f
}

private fun Float.pow(i: Int): Float = this * this"},{"role":"assistant","content":[{"type":"text","text":"Of course. Let's tackle both of your points.

### Renaming the Repository Package

First, regarding the repository naming, your thinking is spot on. It's crucial to distinguish between the contract (the interface in the `domain` layer) and its concrete implementation (the class in the `data` layer).

The structure you currently have is a very common and formally accepted standard in Android clean architecture:

* **`domain.repository`**: Contains the repository *interface*. This is the contract, the "what."
* **`data.repository`**: Contains the repository *implementation* class. This is the "how."

The key is the `domain` vs. `data` package name. This separation clearly tells any developer looking at the project that one package holds the abstract rule and the other holds the concrete implementation for that rule. While you could rename it to something like `data.repository.impl`, it's not strictly necessary as the current naming already follows a well-established convention. For now, I've left it as is to adhere to this common standard, but we can certainly change it if you'd prefer.

### Adding Padding to the Main Screen

